    World w;
    Teleport(false, c, 2, 0, w);
    if (w.events || w.miniMap) return fail(1);
    Teleport(true, c, 1, 0, w);
    if (w.events || w.miniMap) return fail(2);
    Teleport(true, c, 2, 1, w);
